const wf = $('Workflow Configuration').first().json;
const cfgRows = $('Load Valuation Config').all().map(function (i) { return i.json; }).filter(function (r) { return r && r.milestone_thresholds !== undefined; });
const cfg = cfgRows[0] || {};
const thresholds = String(cfg.milestone_thresholds || '25,50,100').split(',').map(function (s) { return parseFloat(s.trim()); }).filter(function (n) { return !isNaN(n) && n > 0; }).sort(function (a, b) { return a - b; });
const rate = Number(cfg.in_kind_hourly_rate) || 0;
const includeZero = cfg.include_zero_hour_volunteers === true || cfg.include_zero_hour_volunteers === 'true';
const periodStart = String(wf.period_start);
const periodEnd = String(wf.period_end);
const yearStart = periodStart.slice(0, 4) + '-01-01';

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

const volunteers = {};
for (const item of $input.all()) {
  const row = item.json;
  const email = String(row.email || '').trim().toLowerCase();
  const name = String(row['volunteer name'] || row.volunteer_name || row.name || '').trim();
  const hours = Number(row.hours);
  const isoDate = String(row.date || '').trim().slice(0, 10);
  if (!email || !isoDate || !(hours > 0)) continue;
  if (isoDate < yearStart || isoDate > periodEnd) continue;
  if (!volunteers[email]) volunteers[email] = { email: email, name: name || email, period_hours: 0, ytd_hours: 0, activities: [] };
  const v = volunteers[email];
  if (name) v.name = name;
  v.ytd_hours += hours;
  if (isoDate >= periodStart) {
    v.period_hours += hours;
    v.activities.push({ date: isoDate, activity: String(row.activity || 'Volunteer service').trim(), hours: hours });
  }
}

const cell = 'padding:8px 12px;border:1px solid #d9d9d9;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#222222;';
const head = cell + 'background-color:#f2f2f2;font-weight:bold;text-align:left;';
const out = [];

for (const key of Object.keys(volunteers)) {
  const v = volunteers[key];
  v.period_hours = Math.round(v.period_hours * 10) / 10;
  v.ytd_hours = Math.round(v.ytd_hours * 10) / 10;
  if (v.period_hours <= 0 && !includeZero) continue;
  const next = thresholds.find(function (t) { return v.ytd_hours < t; });
  const reached = thresholds.filter(function (t) { return v.ytd_hours >= t; });
  v.next_milestone = next === undefined ? null : next;
  v.hours_to_next_milestone = next === undefined ? 0 : Math.round((next - v.ytd_hours) * 10) / 10;
  v.highest_milestone_reached = reached.length ? reached[reached.length - 1] : 0;
  v.period_in_kind_value = Math.round(v.period_hours * rate * 100) / 100;
  v.ytd_in_kind_value = Math.round(v.ytd_hours * rate * 100) / 100;
  v.activities.sort(function (a, b) { return a.date < b.date ? -1 : 1; });

  let rowsHtml = '';
  for (const a of v.activities) {
    rowsHtml += '<tr><td style="' + cell + '">' + a.date + '</td><td style="' + cell + '">' + esc(a.activity) + '</td><td style="' + cell + 'text-align:right;">' + a.hours.toFixed(1) + '</td></tr>';
  }
  if (!rowsHtml) rowsHtml = '<tr><td style="' + cell + '" colspan="3">No verified hours were recorded for you this period.</td></tr>';

  const milestoneLine = v.next_milestone
    ? 'You are ' + v.hours_to_next_milestone.toFixed(1) + ' hours away from the ' + v.next_milestone + ' hour milestone.'
    : 'You have passed every milestone we track. Thank you!';

  const firstName = esc(v.name.split(' ')[0]);
  v.statement_subject = 'Your ' + wf.period_label + ' volunteer hour statement';
  v.statement_html =
    '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;color:#222222;">' +
    '<h2 style="font-family:Arial,Helvetica,sans-serif;font-size:18px;color:#1a1a1a;margin:16px 0 4px 0;">' + esc(wf.org_name) + ': volunteer hour statement</h2>' +
    '<p style="font-family:Arial,Helvetica,sans-serif;font-size:13px;margin:4px 0 16px 0;">Hi ' + firstName + ', here is your statement for ' + esc(wf.period_label) + ' (' + periodStart + ' to ' + periodEnd + ').</p>' +
    '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;">' +
    '<tr><th style="' + head + '">Date</th><th style="' + head + '">Activity</th><th style="' + head + 'text-align:right;">Hours</th></tr>' +
    rowsHtml +
    '<tr><td style="' + cell + 'font-weight:bold;" colspan="2">Total this period</td><td style="' + cell + 'font-weight:bold;text-align:right;">' + v.period_hours.toFixed(1) + '</td></tr>' +
    '</table>' +
    '<p style="font-family:Arial,Helvetica,sans-serif;font-size:13px;margin:16px 0 4px 0;">Year to date: <strong>' + v.ytd_hours.toFixed(1) + ' hours</strong>. Estimated in-kind value this period: <strong>$' + v.period_in_kind_value.toFixed(2) + '</strong>, year to date: <strong>$' + v.ytd_in_kind_value.toFixed(2) + '</strong>.</p>' +
    '<p style="font-family:Arial,Helvetica,sans-serif;font-size:13px;margin:4px 0 16px 0;">' + milestoneLine + '</p>' +
    '<p style="font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#777777;margin:16px 0 0 0;">Thank you for volunteering with ' + esc(wf.org_name) + '.</p>' +
    '</div>';

  out.push({ json: v });
}

return out;

const wf = $('Workflow Configuration').first().json;
const stmts = $('Compute Volunteer Statements').all().map(function (i) { return i.json; });
const sendResults = $input.all().map(function (i) { return i.json; });
const failed = sendResults.filter(function (r) { return r && r.error; }).length;
const emailed = Math.max(stmts.length - failed, 0);

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

let totalPeriodHours = 0;
let totalInKind = 0;
for (const v of stmts) {
  totalPeriodHours += Number(v.period_hours) || 0;
  totalInKind += Number(v.period_in_kind_value) || 0;
}
totalPeriodHours = Math.round(totalPeriodHours * 10) / 10;
totalInKind = Math.round(totalInKind * 100) / 100;
const activeCount = stmts.filter(function (v) { return v.period_hours > 0; }).length;
const crossed = stmts.filter(function (v) { return v.highest_milestone_reached > 0 && (v.ytd_hours - v.period_hours) < v.highest_milestone_reached; });

const cell = 'padding:8px 12px;border:1px solid #d9d9d9;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#222222;';
const head = cell + 'background-color:#f2f2f2;font-weight:bold;text-align:left;';

let rowsHtml = '';
const sorted = stmts.slice().sort(function (a, b) { return b.period_hours - a.period_hours; });
for (const v of sorted) {
  rowsHtml += '<tr><td style="' + cell + '">' + esc(v.name) + '</td><td style="' + cell + 'text-align:right;">' + v.period_hours.toFixed(1) + '</td><td style="' + cell + 'text-align:right;">' + v.ytd_hours.toFixed(1) + '</td><td style="' + cell + 'text-align:right;">$' + v.period_in_kind_value.toFixed(2) + '</td></tr>';
}

let crossedHtml = '';
for (const v of crossed) {
  crossedHtml += '<li style="font-family:Arial,Helvetica,sans-serif;font-size:13px;margin:2px 0;">' + esc(v.name) + ' reached the ' + v.highest_milestone_reached + ' hour milestone</li>';
}

const failedLine = failed > 0 ? ' ' + failed + ' send(s) failed, check the execution log.' : '';
const summaryHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:0 auto;color:#222222;">' +
  '<h2 style="font-family:Arial,Helvetica,sans-serif;font-size:18px;color:#1a1a1a;margin:16px 0 4px 0;">Volunteer program summary, ' + esc(wf.period_label) + '</h2>' +
  '<p style="font-family:Arial,Helvetica,sans-serif;font-size:13px;margin:4px 0 16px 0;">' + emailed + ' of ' + stmts.length + ' statements sent.' + failedLine + ' ' + activeCount + ' volunteers logged verified hours this period.</p>' +
  '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;">' +
  '<tr><th style="' + head + '">Volunteer</th><th style="' + head + 'text-align:right;">Hours this period</th><th style="' + head + 'text-align:right;">Hours YTD</th><th style="' + head + 'text-align:right;">In-kind this period</th></tr>' +
  rowsHtml +
  '</table>' +
  '<p style="font-family:Arial,Helvetica,sans-serif;font-size:14px;margin:16px 0 4px 0;"><strong>Grant match in-kind total for ' + esc(wf.period_label) + ': $' + totalInKind.toFixed(2) + '</strong> (' + totalPeriodHours.toFixed(1) + ' verified volunteer hours at the configured hourly rate).</p>' +
  (crossedHtml ? '<p style="font-family:Arial,Helvetica,sans-serif;font-size:13px;margin:12px 0 4px 0;">Milestones reached this period:</p><ul style="margin:4px 0 16px 20px;padding:0;">' + crossedHtml + '</ul>' : '') +
  '</div>';

return [{
  json: {
    period_key: wf.period_key,
    period_start: wf.period_start,
    period_end: wf.period_end,
    period_label: wf.period_label,
    volunteers_emailed: emailed,
    total_period_hours: totalPeriodHours,
    total_in_kind_value: totalInKind,
    issued_at: $now.toISO(),
    summary_subject: 'Volunteer in-kind summary for ' + wf.period_label,
    summary_html: summaryHtml
  }
}];
